 * @param {string} rule - The rule expression to evaluate (e.g. 'ctx.amount > 100')
 * @param {object} context - The context data to evaluate the rule against
 * @returns {object} Result of the evaluation with a 'result' boolean field
 */
app.post('/check', (req, res) => {
  try {
    if (!req.body.rule) {
      return res.status(400).json({ error: 'Missing required field: rule' });
    }

    if (!req.body.context) {
      return res.status(400).json({ error: 'Missing required field: context' });
    }

    const result = evalRule(req);
    res.json({ result });
  } catch (error) {
    res.status(400).json({ error: `Rule evaluation failed: ${error.message}` });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

